import{_ as l,a0 as n,w as d,s as g,ao as p,I as a,x as i,a1 as s,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"用 git log 命令顯示在特定日期的提交記錄 | LCTT x X-CMD","titleTemplate":false,"description":"用 git log 命令顯示在特定日期的提交記錄 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 git log 命令顯示在特定日期的提交記錄 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 git log 命令顯示在特定日期的提交記錄 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20221024.3 ⭐️ How to display commits created on a specific day with the git log command","title":"用 git log 命令顯示在特定日期的提交記錄","tag":"202211","desc":""},"relativePath":"202211/20221024.3 ⭐️ How to display commits created on a specific day with the git log command.md","filePath":"[post].md"}'),r={name:"202211/20221024.3 ⭐️ How to display commits created on a specific day with the git log command.md"};function c(h,t,u,m,k,b){const e=n("Link");return d(),g("div",null,[t[15]||(t[15]=p('<h1 id="用-git-log-命令顯示在特定日期的提交記錄" tabindex="-1">用 git log 命令顯示在特定日期的提交記錄 <a class="header-anchor" href="#用-git-log-命令顯示在特定日期的提交記錄" aria-label="Permalink to “用 git log 命令顯示在特定日期的提交記錄”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202211/06/085449j5diiljl7dzgdr0z.jpg" alt=""></p><blockquote><p><code>git log</code> 命令是 Git 中一個很重要的查看提交記錄的工具，它也是人們喜歡使用 Git 的原因之一。</p></blockquote><p><code>git log</code> 命令能夠讓你瞭解到更多關於貢獻者 <ruby>提交<rt>commit</rt></ruby> 的記錄。使用 <code>git log</code> 的一種方式是按日期查看提交記錄 。要查看<strong>在指定日期或日期範圍內</strong>創建的 Git 存儲庫中的提交記錄，請使用帶有選項 <code>--since</code> 或 <code>--until</code> 或者同時使用以上兩個選項的 <code>git log</code> 命令。</p><p>首先，進入你要查看的分支（例如，<code>main</code> 分支）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout main</span></span></code></pre></div><p>接下來，你可以使用以下命令，來顯示當前日期（即今天）的提交記錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline --since=&quot;yesterday&quot;</span></span></code></pre></div><p>僅顯示某一特定用户（例如，用户 <code>Agil</code>）在今天的提交記錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline --since=&quot;yesterday&quot; --author=&quot;Agil&quot;</span></span></code></pre></div><p>還可以顯示在某一日期範圍內的提交記錄。使用以下命令，顯示在任意兩個日期之間（例如，2022 年 4 月 22 日至 2022 年 4 月 24 日）的提交記錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline --since=&quot;2022-04-22&quot; --until=&quot;2022-04-24&quot;</span></span></code></pre></div><p>在上面這個例子中，會輸出 2022 年 4 月 22 日至 2022 年 4 月 24 日期間，不包括 2022 年 4 月 22 日的所有提交記錄。如果你想要包括 2022 年 4 月 22 日的提交記錄，請將命令中的 <code>2022-04-22</code> 替換為 <code>2022-04-21</code>。</p><p>運行以下命令，能夠顯示某一特定用户（例如，用户 <code>Agil</code>）在兩個指定的日期之間的提交記錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline --since=&quot;2022-04-22&quot; --until=&quot;2022-04-24&quot; --author=&quot;Agil&quot;</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>Git 有很多優點，其中一個優點就是 Git 讓你能夠收集你項目的相關數據。<code>git log</code> 命令是一個重要的查看提交記錄的工具，也是人們喜歡使用 Git 的原因之一！</p><hr>',18)),a("p",null,[t[1]||(t[1]=i("via: ",-1)),s(e,{href:"https://opensource.com/article/22/10/git-log-command"},{default:o(()=>[...t[0]||(t[0]=[i("https://opensource.com/article/22/10/git-log-command",-1)])]),_:1})]),a("p",null,[t[6]||(t[6]=i("作者：",-1)),s(e,{href:"https://opensource.com/users/agantony"},{default:o(()=>[...t[2]||(t[2]=[i("Agil Antony",-1)])]),_:1}),t[7]||(t[7]=i(" 選題：",-1)),s(e,{href:"https://github.com/lkxed"},{default:o(()=>[...t[3]||(t[3]=[i("lkxed",-1)])]),_:1}),t[8]||(t[8]=i(" 譯者：",-1)),s(e,{href:"https://github.com/chai001125"},{default:o(()=>[...t[4]||(t[4]=[i("chai001125",-1)])]),_:1}),t[9]||(t[9]=i(" 校對：",-1)),s(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[5]||(t[5]=[i("wxy",-1)])]),_:1})]),a("p",null,[t[12]||(t[12]=i("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[10]||(t[10]=[i("LCTT",-1)])]),_:1}),t[13]||(t[13]=i(" 原創編譯，",-1)),s(e,{href:"https://linux.cn/"},{default:o(()=>[...t[11]||(t[11]=[i("Linux中國",-1)])]),_:1}),t[14]||(t[14]=i(" 榮譽推出",-1))])])}const x=l(r,[["render",c]]);export{C as __pageData,x as default};
